import numpy as np
F=np.load('source_pixels.npz')['rgb']
for i in [0,4,8,12,16,20,24,48,95]:
 print('\\nFRAME',i)
 for y in [100,105,110,115,120,125]:
  # segments of colors x 0:210, run-length quantized
  a=F[i,y,:210]
